import type { MediaAsset } from "@/types/guide";
import { CITY_GALLERY } from "./gallery";

const BASE = "https://resource.tapzm.com";

function fromGallery(slug: string, file: string): MediaAsset | undefined {
  const url = `${BASE}/media/cities/${slug}/${file}`;
  return CITY_GALLERY[slug]?.find((photo) => photo.url === url);
}

function hosted(
  path: string,
  alt: string,
  location: string,
  source: string,
  author: string,
  license: string,
  originalUrl: string,
): MediaAsset {
  return { url: `${BASE}${path}`, alt, location, source, author, license, originalUrl };
}

export const ATTRACTION_PHOTOS: Record<string, Record<string, MediaAsset>> = {};
export const DISH_PHOTOS: Record<string, Record<string, MediaAsset>> = {};

function setAtt(slug: string, name: string, photo: MediaAsset | undefined) {
  if (!photo) return;
  ATTRACTION_PHOTOS[slug] ??= {};
  ATTRACTION_PHOTOS[slug][name] = photo;
}

function setDish(slug: string, name: string, photo: MediaAsset | undefined) {
  if (!photo) return;
  DISH_PHOTOS[slug] ??= {};
  DISH_PHOTOS[slug][name] = photo;
}

